using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;
[InitializeOnLoad]public static class HospitalOpenRoadsideFinish{static HospitalOpenRoadsideFinish(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||!File.Exists("HospitalOpenRoadsideFinish.request"))return;File.Delete("HospitalOpenRoadsideFinish.request");try{Run();}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/HospitalOpenRoadside.txt",e.ToString());Debug.LogException(e);}}struct V{public Vector3 p;public Vector2[] uv;}static void Run(){const string d="Assets/Scenes/Oasis/CityHospital/";var scene=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");var f=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshFilter>(true)).Single(g=>g.name=="billboard (8)");var matrix=f.transform.localToWorldMatrix;float cutoff=35.34f;string lowerPath=d+"Hospital billboard 8 original pole platform.asset";var lower=AssetDatabase.LoadAssetAtPath<Mesh>(lowerPath);if(!lower){var data=typeof(FinalPNGCityDetails).GetMethod("Read",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{f.sharedMesh});var p=(Vector3[])data.GetType().GetField("p").GetValue(data);var uv=(Vector2[][])data.GetType().GetField("uv").GetValue(data);var ids=(int[])data.GetType().GetField("ids").GetValue(data);var pp=new List<Vector3>();var uu=Enumerable.Range(0,8).Select(c=>new List<Vector2>()).ToArray();var ii=new List<int>();Func<int,V> vertex=i=>new V{p=p[i],uv=Enumerable.Range(0,8).Select(c=>uv[c]!=null?uv[c][i]:Vector2.zero).ToArray()};Func<V,V,float,V> mix=(a,b,t)=>new V{p=Vector3.Lerp(a.p,b.p,t),uv=Enumerable.Range(0,8).Select(c=>Vector2.Lerp(a.uv[c],b.uv[c],t)).ToArray()};for(int k=0;k<ids.Length;k+=3){var poly=new[]{vertex(ids[k]),vertex(ids[k+1]),vertex(ids[k+2])};var clipped=new List<V>();for(int j=0;j<3;j++){var a=poly[j];var b=poly[(j+1)%3];float ay=f.transform.TransformPoint(a.p).y,by=f.transform.TransformPoint(b.p).y;bool ain=ay<=cutoff,bin=by<=cutoff;if(ain)clipped.Add(a);if(ain!=bin)clipped.Add(mix(a,b,(cutoff-ay)/(by-ay)));}for(int j=1;j<clipped.Count-1;j++){int n=pp.Count;foreach(var v in new[]{clipped[0],clipped[j],clipped[j+1]}){pp.Add(v.p);for(int c=0;c<8;c++)uu[c].Add(v.uv[c]);}ii.AddRange(new[]{n,n+1,n+2});}}lower=new Mesh{name="Billboard 8 original retained pole and platform"};lower.SetVertices(pp);for(int c=0;c<8;c++)if(uv[c]!=null)lower.SetUVs(c,uu[c]);lower.SetTriangles(ii,0);lower.RecalculateNormals();lower.RecalculateTangents();lower.RecalculateBounds();AssetDatabase.CreateAsset(lower,lowerPath);}f.sharedMesh=lower;PrefabUtility.RecordPrefabInstancePropertyModifications(f);var collider=f.GetComponent<MeshCollider>();if(collider){collider.sharedMesh=lower;PrefabUtility.RecordPrefabInstancePropertyModifications(collider);}var mat=AssetDatabase.LoadAssetAtPath<Material>(d+"City Hospital Mobile.mat");var root=scene.GetRootGameObjects().Single(g=>g.name=="Hospital billboard 8 low poly branding"||g.name=="Hospital billboard 8 massive open 3D branding");root.name="Hospital billboard 8 massive open 3D branding";root.transform.position=new Vector3(-93.156f,cutoff+1.96f,-299.934f);var counts=new int[2];for(int l=0;l<2;l++){var mesh=StackHouse3DSigns.BuildHospitalOpenRoadside(mat,l==0);counts[l]=mesh.triangles.Length/3;var asset=AssetDatabase.LoadAssetAtPath<Mesh>(d+"Hospital billboard 8 "+(l==0?"near":"far")+".asset");asset.Clear();asset.indexFormat=mesh.indexFormat;asset.vertices=mesh.vertices;for(int ch=0;ch<8;ch++){var values=new List<Vector4>();mesh.GetUVs(ch,values);if(values.Count>0)asset.SetUVs(ch,values);}asset.normals=mesh.normals;asset.tangents=mesh.tangents;asset.triangles=mesh.triangles;asset.bounds=mesh.bounds;UnityEngine.Object.DestroyImmediate(mesh);EditorUtility.SetDirty(asset);asset.UploadMeshData(false);foreach(var filter in root.GetComponentsInChildren<MeshFilter>(true).Where(v=>v.sharedMesh==asset)){filter.sharedMesh=null;filter.sharedMesh=asset;}}root.GetComponent<LODGroup>().RecalculateBounds();PrefabUtility.SaveAsPrefabAsset(root,d+"Hospital billboard 8 low poly branding.prefab");if(f.transform.localToWorldMatrix!=matrix)throw new Exception("Native pole transform changed");AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);var capture=typeof(FinalPNGCityDetails).GetMethod("Capture",BindingFlags.Static|BindingFlags.NonPublic);capture.Invoke(null,new object[]{scene,new Vector3(-80,40,-280),new Vector3(-93,35.8f,-300),"Hospital-Billboard-8-Open-3D-Front"});capture.Invoke(null,new object[]{scene,new Vector3(-107,40,-320),new Vector3(-93,35.8f,-300),"Hospital-Billboard-8-Open-3D-Back"});File.WriteAllText("FinalEnvironmentRoadReview/HospitalOpenRoadside.txt","SUCCESS rectangular advertising head and all rectangular replacement panels removed. Native pole/platform retained at original transform; detached raised CITY and HOSPITAL letters with massive freestanding medical cross; narrow rear supports only. Existing hospital atlas/material, no new textures/materials/lights. Two sided readable geometry; near="+counts[0]+" triangles, far="+counts[1]+" triangles, distance LOD and prefab saved. Shader errors="+ShaderUtil.ShaderHasError(mat.shader));}}
